import { useEffect } from 'react';
import { getDocument } from '@atlaskit/browser-apis';
import { installScrollbarHarmonisation } from './install-scrollbar-harmonisation';
export function useScrollbarHarmonisation(isEnabled) {
  useEffect(function () {
    if (!isEnabled) {
      return;
    }
    var targetDocument = getDocument();
    if (!targetDocument) {
      return;
    }
    return installScrollbarHarmonisation(targetDocument);
  }, [isEnabled]);
}